        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            pid, emp, dr = o["punch_id"], o["employee"], o["direction"]
            ts = int(o["epoch_ms"]) // 1000
        else:
            pid, emp, dr = o["id"], o["emp"], o["dir"]
            ts = int(o["ts"]) if "ts" in o else int(o["ts_ms"]) // 1000
        out.append((str(pid), emp, dr.upper(), ts))
    return out


def parse_offset_csv(path, tz):
    out = []
    for row in csv.reader(io.StringIO(read_text(path)), delimiter=";"):
        if not row or row[0] == "punch_id" or not any(row):
            continue
        pid, emp, ev, ts = (c.strip() for c in row[:4])
        dr = "IN" if ev.lower().endswith("in") else "OUT"
        out.append((pid, emp, dr, epoch_of(datetime.fromisoformat(ts))))
    return out


def parse_legacy(path, tz):
    out = []
    default = standard_offset(tz)
    off = default
    for line in lines_of(path):
        line = line.rstrip("\r\n")
        k = line[0]
        if k == "H":
            tail = line[13:18].strip()
            off = parse_offset(tail) if len(tail) == 5 and tail[0] in "+-" else default
        elif k == "D":
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = "IN" if line[15] == "I" else "OUT"
            dt = datetime.strptime(line[16:30], "%Y%m%d%H%M%S")
            ts = epoch_of(dt.replace(tzinfo=UTC) - off)
            out.append((pid, "E" + badge, dr, ts))
    return out


def parse_de(path, tz):
    out = []
    header = None
    for line in lines_of(path):
        cells = [c.strip() for c in line.split("\t")]
        if "Ausweis" in cells:
            header = {n: i for i, n in enumerate(cells)}
            continue
        if header is None:
            continue
        g = lambda n: cells[header[n]]
        naive = datetime.strptime(g("Datum") + " " + g("Uhrzeit"), "%d.%m.%Y %H:%M")
        z = g("Zeitzone").upper()
        dst = True if z == "MESZ" else (False if z == "MEZ" else None)
        out.append((g("Nr"), g("Ausweis"), "IN" if g("Buchung").upper() == "K" else "OUT",
                    local_to_epoch(naive, tz, dst)))
    return out


def parse_local_csv(path, tz):
    out = []
    header = None
    for row in csv.reader(io.StringIO(read_text(path))):
        if not row or not any(c.strip() for c in row):
            continue
        cells = [c.strip() for c in row]
        if "employee_id" in cells:
            header = {n: i for i, n in enumerate(cells)}
            continue
        if header is None:
            continue
        g = lambda n: cells[header[n]]
        naive = datetime.strptime(g("local_time"), "%Y-%m-%d %H:%M:%S")
        out.append((g("punch_ref"), g("employee_id"), g("direction").upper(), local_to_epoch(naive, tz, None)))
    return out


def parse_local_jsonl(path, tz):
    out = []
    for line in lines_of(path):
        o = json.loads(line)
        p = o.get("punch")
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        pid = p["id"]
        out.append((str(pid), p["badge"], p["type"].upper(), local_to_epoch(naive, tz, None)))
    return out


PARSERS = {
    "abbr-csv": parse_abbr, "epoch-jsonl": parse_epoch, "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy, "de-tsv": parse_de, "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


# ---------------------------------------------------------------- main logic
def round_punch(ts, tz):
    off = int(datetime.fromtimestamp(ts, tz).utcoffset().total_seconds())
    local = ts + off
    r = ((local + 180) // 360) * 360
    return r - off


def night_seconds(a, b, tz):
    """Seconds of [a, b) epoch between 22:00 and 06:00 local in tz."""
    if b <= a:
        return 0
    d0 = datetime.fromtimestamp(a, tz).date() - timedelta(days=1)
    d1 = datetime.fromtimestamp(b, tz).date() + timedelta(days=1)
    total = 0
    d = d0
    while d <= d1:
        s = local_to_epoch(datetime(d.year, d.month, d.day, 22), tz)
        n = d + timedelta(days=1)
        e = local_to_epoch(datetime(n.year, n.month, n.day, 6), tz)
        lo, hi = max(a, s), min(b, e)
        if hi > lo:
            total += hi - lo
        d += timedelta(days=1)
    return total


def half_up(fr):
    cents = fr * 100
    return int((cents + Fraction(1, 2)).__floor__())


def main(inp, outp):
    inp = Path(inp)
    period = json.loads((inp / "period.json").read_text())
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = epoch_of(datetime.fromisoformat(period["corrections_cutoff"].replace("Z", "+00:00")))

    with open(inp / "sites.csv", newline="", encoding="utf-8-sig") as f:
        sites = {r["site"].strip(): (ZoneInfo(r["timezone"].strip()), r["format"].strip())
                 for r in csv.DictReader(f)}
    with open(inp / "employees.csv", newline="", encoding="utf-8-sig") as f:
        employees = [(r["employee_id"].strip(), r["home_site"].strip()) for r in csv.DictReader(f)]
    home_tz = {e: sites[h][0] for e, h in employees}
    rates = {}
    with open(inp / "rates.csv", newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            rates.setdefault(r["employee_id"].strip(), []).append(
                (date.fromisoformat(r["effective_from"].strip()), Fraction(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}  # (site, id) -> [emp, dir, ts]
    for site, (tz, fmt) in sites.items():
        d = inp / "exports" / site
        if not d.is_dir():
            continue
        for p in sorted(d.rglob("*")):
            if not p.is_file():
                continue
            for pid, emp, dr, ts in PARSERS[fmt](p, tz):
                punches.setdefault((site, pid), [emp.strip(), dr, ts])
    ever = set(punches)

    # 2. corrections
    corr = []
    cdir = inp / "corrections"
    if cdir.is_dir():
        for p in sorted(cdir.rglob("*")):
            if p.is_file():
                for r in csv.DictReader(io.StringIO(read_text(p))):
                    r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                    if not r.get("correction_id"):
                        continue
                    r["_at"] = epoch_of(datetime.fromisoformat(r["issued_at"].replace("Z", "+00:00")))
                    corr.append(r)
    corr = [c for c in corr if c["_at"] <= cutoff]
    corr.sort(key=lambda c: (c["_at"], c["correction_id"]))
    applied = 0
    voided = set()
    for c in corr:
        key = (c["site"], c["punch_id"])
        act = c["action"].lower()
        if act == "void":
            if key in punches and key not in voided:
                del punches[key]
                voided.add(key)
                applied += 1
        elif act == "set":
            if key in punches:
                punches[key][2] = epoch_of(datetime.fromisoformat(c["time"].replace("Z", "+00:00")))
                applied += 1
        elif act == "add":
            if key not in ever:
                punches[key] = [c["employee"], c["type"].upper(),
                                epoch_of(datetime.fromisoformat(c["time"].replace("Z", "+00:00")))]
                ever.add(key)
                applied += 1

    emp_ids = {e for e, _ in employees}
    by_emp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emp_ids:
            by_emp.setdefault(emp, []).append((ts, 0 if dr == "OUT" else 1, site, pid, dr))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0) for e, _ in employees}
    gross = {e: Fraction(0) for e, _ in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def in_period(emp, rts):
        wd = datetime.fromtimestamp(rts, home_tz[emp]).date()
        return wd, pstart <= wd <= pend

    for emp, lst in by_emp.items():
        lst.sort()
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            rts = round_punch(ts, sites[site][0])
            if last is not None and last[4] == dr and ts - last[0] <= 300:
                if in_period(emp, rts)[1]:
                    exc["duplicates_dropped"] += 1
                continue
            last = (ts, 0, site, pid, dr)
            kept.append((rts, dr, site))
        shifts = []
        cur = None
        for rts, dr, site in kept:
            if dr == "IN":
                if cur:
                    if in_period(emp, cur[0])[1]:
                        exc["open_shifts"] += 1
                cur = (rts, site)
            else:
                if cur and rts - cur[0] <= 16 * 3600:
                    shifts.append((cur[0], rts, cur[1]))
                    cur = None
                else:
                    if cur:
                        if in_period(emp, cur[0])[1]:
                            exc["open_shifts"] += 1
                        cur = None
                    if in_period(emp, rts)[1]:
                        exc["orphan_outs"] += 1
        if cur and in_period(emp, cur[0])[1]:
            exc["open_shifts"] += 1

        rows = []
        for a, b, site in shifts:
            wd, ok = in_period(emp, a)
            if not ok:
                continue
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_seconds(a, b, sites[site][0]) // 60, paid)
            rows.append([a, wd, paid, night, 0, 0])  # daily ot, weekly ot
        rows.sort(key=lambda r: r[0])
        day_tot = {}
        for r in rows:
            before = day_tot.get(r[1], 0)
            after = before + r[2]
            r[4] = max(0, after - max(before, 480))
            day_tot[r[1]] = after
        week_tot = {}
        for r in rows:
            wk = r[1] - timedelta(days=r[1].weekday())
            reg = r[2] - r[4]
            before = week_tot.get(wk, 0)
            after = before + reg
            r[5] = max(0, after - max(before, 2400))
            week_tot[wk] = after
        for a, wd, paid, night, dot, wot in rows:
            ot = dot + wot
            reg = paid - ot
            rate = None
            for eff, rt in rates.get(emp, []):
                if eff <= wd:
                    rate = rt
            if rate is None:
                rate = rates[emp][0][1] if rates.get(emp) else Fraction(0)
            gross[emp] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            s = res[emp]
            s["shifts"] += 1
            s["paid_minutes"] += paid
            s["overtime_minutes"] += ot
            s["night_minutes"] += night

    totals = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = 0
    out_emps = {}
    for e, _ in employees:
        c = half_up(gross[e])
        tg += c
        for k in totals:
            totals[k] += res[e][k]
        out_emps[e] = dict(res[e], gross="%d.%02d" % divmod(c, 100))
    totals["gross"] = "%d.%02d" % divmod(tg, 100)
    result = {"period": {"start": period["start"], "end": period["end"]},
              "employees": out_emps, "exceptions": exc, "totals": totals}
    Path(outp).write_text(json.dumps(result, indent=1))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
